//! Kani proofs for the fee maths, `credited_input` and `settlement`.
//! Generated by the Book of Knowledge verification run; see `.bok/confirmed-invariants/`.

/// Runs `$body` with `$b` bound to one of the rates the bounded tiers cover: 0, 1, 25,
/// 333, 9_999, 10_000, 10_001 and 65_535 bps. Each arm binds a constant, so CBMC sees a
/// multiplication by a constant (cheap) rather than by a symbolic rate (which, combined
/// with the 128-bit division, does not finish).
macro_rules! with_edge_rate {
    ($b:ident => $body:expr) => {{
        match kani::any::<u8>() % 8 {
            0 => {
                let $b: u64 = 0;
                $body
            }
            1 => {
                let $b: u64 = 1;
                $body
            }
            2 => {
                let $b: u64 = 25;
                $body
            }
            3 => {
                let $b: u64 = 333;
                $body
            }
            4 => {
                let $b: u64 = 9_999;
                $body
            }
            5 => {
                let $b: u64 = 10_000;
                $body
            }
            6 => {
                let $b: u64 = 10_001;
                $body
            }
            _ => {
                let $b: u64 = 65_535;
                $body
            }
        }
    }};
}

mod credit;
mod fees;
mod settle;
